package com.pif.api.actuarial;

import static com.pif.api.actuarial.Js.obj;
import java.util.*;
import java.util.stream.IntStream;

/** Annual cumulative development triangles. Missing observations are never treated as zero. */
final class Reserving {
  static final String VERSION="pif-reserving-1.0.0";
  static final List<String> AVERAGES=List.of("VOLUME_WEIGHTED","SIMPLE_AVERAGE","LATEST_DIAGONALS");
  static final List<String> METHODS=List.of("CHAIN_LADDER_PAID","CHAIN_LADDER_INCURRED","EXPECTED_LOSS_RATIO","BORNHUETTER_FERGUSON_PAID","BORNHUETTER_FERGUSON_INCURRED");
  static final List<String> LABELS=List.of("Chain ladder (paiements)","Chain ladder (survenus)","Ratio sinistres/primes attendu","Bornhuetter–Ferguson (paiements)","Bornhuetter–Ferguson (survenus)");
  static final Map<String,Object> LIMITS=obj("minOrigins",3,"maxOrigins",25,"minFirstOrigin",1950,"maxFirstOrigin",2100,"maxAmount",1e12,"minFactor",.1,"maxFactor",100,"minTail",.5,"maxTail",3,"minLossRatio",.01,"maxLossRatio",5);
  static final class InputError extends RuntimeException { final String code;InputError(String message){this(message,"INVALID_TRIANGLE");}InputError(String message,String code){super(message);this.code=code;} }
  record Data(int firstOrigin,List<List<Double>> paid,List<List<Double>> incurred,List<Double> premiums) { Map<String,Object> json(){return obj("firstOrigin",firstOrigin,"paid",paid,"incurred",incurred,"premiums",premiums);} }
  record Assumptions(String average,Integer latestDiagonals,double paidTail,double incurredTail,List<Double> paidFactors,List<Double> incurredFactors,Double lossRatio) {
    Map<String,Object> json(){return obj("average",average,"latestDiagonals",average.equals("LATEST_DIAGONALS")?latestDiagonals:null,"tail",obj("paid",paidTail,"incurred",incurredTail),"selectedFactors",obj("paid",paidFactors,"incurred",incurredFactors),"expectedLossRatio",lossRatio);}
    Assumptions average(String name,Integer recent){return new Assumptions(name,recent,paidTail,incurredTail,paidFactors,incurredFactors,lossRatio);}
    Assumptions tails(){return new Assumptions(average,latestDiagonals,Math.min(3,paidTail+.05),Math.min(3,incurredTail+.05),paidFactors,incurredFactors,lossRatio);}
    Assumptions loss(double ratio){return new Assumptions(average,latestDiagonals,paidTail,incurredTail,paidFactors,incurredFactors,ratio);}
    Assumptions factors(boolean paid,List<Double> f){return new Assumptions(average,latestDiagonals,paidTail,incurredTail,paid?f:paidFactors,paid?incurredFactors:f,lossRatio);}
  }
  record Factor(int from,int to,int pairs,Double volumeWeighted,Double simpleAverage,Double latestDiagonals,Double min,Double max,Double estimated,double selected,String source){}
  record Origin(int origin,int age,double latest,double cdf,double ultimate,double development){}
  record Totals(double latest,double ultimate,double development){}
  record Chain(String basis,List<Factor> factors,double tail,List<Double> cdf,List<Double> percentDeveloped,List<List<Double>> linkRatios,List<List<Double>> incremental,List<List<Double>> projected,List<Origin> origins,Totals totals){}
  record MethodOrigin(int origin,double ultimate,double unpaid,Double ibnr){}
  record Estimate(String method,List<MethodOrigin> origins,String reason) {
    boolean available(){return origins!=null;}
    double ultimate(){return origins.stream().mapToDouble(MethodOrigin::ultimate).sum();}
    double unpaid(){return origins.stream().mapToDouble(MethodOrigin::unpaid).sum();}
    Map<String,Object> json(){return available()?obj("method",method,"available",true,"origins",origins,"totals",obj("ultimate",sum(origins.stream().map(MethodOrigin::ultimate).toList()),"unpaid",sum(origins.stream().map(MethodOrigin::unpaid).toList()),"ibnr",origins.getFirst().ibnr()==null?null:sum(origins.stream().map(MethodOrigin::ibnr).toList()))):obj("method",method,"available",false,"reason",reason);}
  }
  record Core(Chain paid,Chain incurred,List<Estimate> methods){}
  static double sum(List<Double> values){double total=0;for(double v:values)total+=v;return total;}
  static void validate(Data d,Assumptions a){int n=d.paid().size();if(n<3||n>25)throw new InputError("a triangle needs 3 to 25 accident years");if(d.firstOrigin()<1950||d.firstOrigin()+n-1>2100)throw new InputError("accident years must lie between 1950 and 2100");triangle("paid",d.paid(),n,d.firstOrigin());if(d.incurred()!=null)triangle("incurred",d.incurred(),n,d.firstOrigin());
    if(d.premiums()!=null){if(d.premiums().size()!=n)throw new InputError("earned premiums must list "+n+" amounts, one per accident year");for(int i=0;i<n;i++){Double p=d.premiums().get(i);if(p==null||!Double.isFinite(p)||p<=0||p>1e12)throw new InputError("the earned premium of accident year "+(d.firstOrigin()+i)+" must be a positive amount");}}
    if(a.average().equals("LATEST_DIAGONALS")&&(a.latestDiagonals()==null||a.latestDiagonals()<1||a.latestDiagonals()>n-1))throw new InputError("the number of latest calendar years must be a whole number from 1 to "+(n-1));
    if(!Double.isFinite(a.paidTail())||a.paidTail()<.5||a.paidTail()>3)throw new InputError("the paid tail factor must be from 0.5 to 3");if(!Double.isFinite(a.incurredTail())||a.incurredTail()<.5||a.incurredTail()>3)throw new InputError("the incurred tail factor must be from 0.5 to 3");factors("paid",a.paidFactors(),n);factors("incurred",a.incurredFactors(),n);if(a.incurredFactors()!=null&&d.incurred()==null)throw new InputError("incurred factors were selected but no incurred triangle was given");if(a.lossRatio()!=null&&(!Double.isFinite(a.lossRatio())||a.lossRatio()<.01||a.lossRatio()>5))throw new InputError("the expected loss ratio must be from 0.01 to 5");}
  static void triangle(String label,List<List<Double>> rows,int n,int first){if(rows.size()!=n)throw new InputError("the "+label+" triangle must have "+n+" rows, one per accident year");for(int i=0;i<n;i++){var row=rows.get(i);int year=first+i;if(row==null||row.size()!=n-i)throw new InputError("accident year "+year+" of the "+label+" triangle must have "+(n-i)+" amounts (development years 1 to "+(n-i)+")");for(int j=0;j<row.size();j++){Double v=row.get(j);if(v==null)continue;String where=label+" amount for accident year "+year+", development year "+(j+1);if(!Double.isFinite(v))throw new InputError("the "+where+" is not a number");if(v<0)throw new InputError("the "+where+" is negative; cumulative amounts cannot be below zero");if(v>1e12)throw new InputError("the "+where+" exceeds 1e+12");}if(row.getLast()==null)throw new InputError("the latest "+label+" amount of accident year "+year+" (development year "+(n-i)+") is missing; the reserve of that year cannot be estimated without it");}}
  static void factors(String label,List<Double> f,int n){if(f==null)return;if(f.size()!=n-1)throw new InputError("the selected "+label+" factors must list "+(n-1)+" values (null keeps the estimate)");for(int j=0;j<f.size();j++){Double v=f.get(j);if(v!=null&&(!Double.isFinite(v)||v<.1||v>100))throw new InputError("the selected "+label+" factor from development year "+(j+1)+" to "+(j+2)+" must be a number from 0.1 to 100");}}
  static Chain chain(String basis,List<List<Double>> triangle,int first,Assumptions a){int n=triangle.size();boolean paid=basis.equals("PAID");String label=paid?"paid":"incurred";var overrides=paid?a.paidFactors():a.incurredFactors();double tail=paid?a.paidTail():a.incurredTail();Integer k=a.average().equals("LATEST_DIAGONALS")?a.latestDiagonals():null;List<Factor> factors=new ArrayList<>();List<String>missing=new ArrayList<>();
    for(int j=0;j<n-1;j++){double num=0,den=0,rnum=0,rden=0;int pairs=0;List<Double> ratios=new ArrayList<>();for(int i=0;i<=n-2-j;i++){Double x=triangle.get(i).get(j),y=triangle.get(i).get(j+1);if(x==null||y==null)continue;pairs++;num+=y;den+=x;if(x>0)ratios.add(y/x);if(k!=null&&i+j+1>=n-k){rnum+=y;rden+=x;}}
      Double volume=den>0?num/den:null,simple=ratios.isEmpty()?null:sum(ratios)/ratios.size(),recent=k!=null&&rden>0?rnum/rden:null,estimated=a.average().equals("VOLUME_WEIGHTED")?volume:a.average().equals("SIMPLE_AVERAGE")?simple:recent;Double override=overrides==null?null:overrides.get(j),selected=override==null?estimated:override;if(selected==null)missing.add((j+1)+" to "+(j+2));factors.add(new Factor(j+1,j+2,pairs,volume,simple,recent,ratios.isEmpty()?null:Collections.min(ratios),ratios.isEmpty()?null:Collections.max(ratios),estimated,selected==null?Double.NaN:selected,override==null?"ESTIMATED":"SELECTED"));}
    if(!missing.isEmpty())throw new InputError("no "+label+" development factor can be estimated from development year "+String.join(", ",missing)+": every pair of amounts is missing or starts from zero. Enter a selected factor for "+(missing.size()==1?"this period":"these periods"),"FACTOR_UNDEFINED");
    List<Double>cdf=new ArrayList<>(Collections.nCopies(n,0d));cdf.set(n-1,tail);for(int j=n-2;j>=0;j--)cdf.set(j,factors.get(j).selected()*cdf.get(j+1));List<List<Double>>link=new ArrayList<>(),incremental=new ArrayList<>(),projected=new ArrayList<>();List<Origin>origins=new ArrayList<>();double totalLatest=0,totalUltimate=0,totalDevelopment=0;
    for(int i=0;i<n;i++){var row=triangle.get(i);List<Double>ratios=new ArrayList<>(),inc=new ArrayList<>(),full=new ArrayList<>(row);for(int j=0;j<row.size();j++){Double v=row.get(j);if(j<row.size()-1){Double next=row.get(j+1);ratios.add(v!=null&&next!=null&&v>0?next/v:null);}inc.add(j==0?v:v!=null&&row.get(j-1)!=null?v-row.get(j-1):null);}double value=row.getLast();for(int j=row.size();j<n;j++){value*=factors.get(j-1).selected();full.add(value);}link.add(ratios);incremental.add(inc);projected.add(full);int age=n-i;double latest=row.get(age-1),ultimate=latest*cdf.get(age-1),development=ultimate-latest;origins.add(new Origin(first+i,age,latest,cdf.get(age-1),ultimate,development));totalLatest+=latest;totalUltimate+=ultimate;totalDevelopment+=development;}
    return new Chain(basis,factors,tail,cdf,cdf.stream().map(v->1/v).toList(),link,incremental,projected,origins,new Totals(totalLatest,totalUltimate,totalDevelopment));
  }
  static Estimate estimate(String method,List<Double>ultimates,Chain paid,Chain incurred,int first){List<MethodOrigin> rows=new ArrayList<>();for(int i=0;i<ultimates.size();i++){double u=ultimates.get(i);rows.add(new MethodOrigin(first+i,u,u-paid.origins().get(i).latest(),incurred==null?null:u-incurred.origins().get(i).latest()));}return new Estimate(method,rows,null);}
  static Core core(Data d,Assumptions a){var p=chain("PAID",d.paid(),d.firstOrigin(),a);var inc=d.incurred()==null?null:chain("INCURRED",d.incurred(),d.firstOrigin(),a);List<Double>prior=d.premiums()!=null&&a.lossRatio()!=null?d.premiums().stream().map(v->v*a.lossRatio()).toList():null;String noPrior=d.premiums()==null?"Earned premiums per accident year are needed.":"An expected loss ratio is needed.",noInc="No incurred (reported) triangle was given.";List<Estimate>out=new ArrayList<>();
    for(int j=0;j<METHODS.size();j++){String method=METHODS.get(j);if((j==1||j==4)&&inc==null){out.add(new Estimate(method,null,noInc));continue;}if(j>=2&&prior==null){out.add(new Estimate(method,null,noPrior));continue;}List<Double>u=new ArrayList<>();for(int i=0;i<d.paid().size();i++){var po=p.origins().get(i);var io=inc==null?null:inc.origins().get(i);u.add(switch(j){case 0->po.ultimate();case 1->io.ultimate();case 2->prior.get(i);case 3->po.latest()+prior.get(i)*(1-1/po.cdf());default->io.latest()+prior.get(i)*(1-1/io.cdf());});}out.add(estimate(method,u,p,inc,d.firstOrigin()));}return new Core(p,inc,out);}
  static Map<String,Object> unpaid(Core c){Map<String,Object>out=new LinkedHashMap<>();for(var e:c.methods())out.put(e.method(),e.available()?sum(e.origins().stream().map(MethodOrigin::unpaid).toList()):null);return out;}
  static Map<String,Object> difference(Map<String,Object> values,Map<String,Object>base){Map<String,Object>out=new LinkedHashMap<>();for(String m:METHODS){Double a=(Double)values.get(m),b=(Double)base.get(m);out.put(m,a==null||b==null?null:a-b);}return out;}
  static Map<String,Object> sensitivity(Data d,Assumptions a,Core base){var b=unpaid(base);List<Object>scenarios=new ArrayList<>();scenarios.add(obj("id","base","label","Base assumptions","unpaid",b,"change",difference(b,b),"note",null));
    if(!a.average().equals("VOLUME_WEIGHTED"))scenario(scenarios,d,a.average("VOLUME_WEIGHTED",null),b,"volume-weighted","Factors: volume-weighted average, all years");if(!a.average().equals("SIMPLE_AVERAGE"))scenario(scenarios,d,a.average("SIMPLE_AVERAGE",null),b,"simple-average","Factors: simple average of link ratios");int recent=Math.min(3,d.paid().size()-1);if(!(a.average().equals("LATEST_DIAGONALS")&&Objects.equals(a.latestDiagonals(),recent)))scenario(scenarios,d,a.average("LATEST_DIAGONALS",recent),b,"latest-diagonals","Factors: volume-weighted, latest "+recent+" calendar years");scenario(scenarios,d,a.tails(),b,"tail-up","Tail factors +0.05");
    if(a.lossRatio()!=null&&d.premiums()!=null)for(int sign:new int[]{1,-1}){double lr=a.lossRatio()*(1+sign*.1);scenario(scenarios,d,a.loss(lr),b,sign>0?"loss-ratio-up":"loss-ratio-down","Expected loss ratio "+(sign>0?"+":"−")+"10% ("+fixed(lr*100,1)+"%)");}
    List<Object>factors=new ArrayList<>();for(var cl:Arrays.asList(base.paid(),base.incurred())){if(cl==null)continue;for(int j=0;j<cl.factors().size();j++){List<Double>shocked=new ArrayList<>(cl.factors().stream().map(Factor::selected).toList());shocked.set(j,shocked.get(j)*1.01);boolean paid=cl.basis().equals("PAID");var changed=chain(cl.basis(),paid?d.paid():d.incurred(),d.firstOrigin(),a.factors(paid,shocked));var f=cl.factors().get(j);factors.add(obj("basis",cl.basis(),"from",f.from(),"to",f.to(),"change",changed.totals().ultimate()-cl.totals().ultimate()));}}
    return obj("scenarios",scenarios,"factors",factors);
  }
  static void scenario(List<Object>out,Data d,Assumptions a,Map<String,Object>base,String id,String label){try{var u=unpaid(core(d,a));out.add(obj("id",id,"label",label,"unpaid",u,"change",difference(u,base),"note",null));}catch(InputError e){out.add(obj("id",id,"label",label,"unpaid",Map.of(),"change",Map.of(),"note",com.pif.api.web.Messages.format("actuarial.not_computable",e.getMessage())));}}
  static String fixed(double n,int digits){return new java.math.BigDecimal(n).setScale(digits,java.math.RoundingMode.HALF_UP).toPlainString();}
  static String cells(List<String>values){return values.size()>4?String.join("; ",values.subList(0,4))+" and "+(values.size()-4)+" more":String.join("; ",values);}
  static void warning(List<Object>out,String code,String message){out.add(obj("code",code,"message",message));}
  static List<Object> warnings(Data d,Assumptions a,Core c){List<Object>out=new ArrayList<>();int n=d.paid().size();for(var cl:Arrays.asList(c.paid(),c.incurred())){if(cl==null)continue;boolean paid=cl.basis().equals("PAID");String label=paid?"paid":"incurred";var triangle=paid?d.paid():d.incurred();List<String>missing=new ArrayList<>(),zero=new ArrayList<>();for(int i=0;i<n;i++){var row=triangle.get(i);for(int j=0;j<row.size();j++){Double v=row.get(j);String cell=(d.firstOrigin()+i)+" year "+(j+1);if(v==null)missing.add(cell);else if(v==0&&j<row.size()-1&&row.get(j+1)!=null&&row.get(j+1)>0)zero.add(cell);}}
      if(!missing.isEmpty())warning(out,cl.basis()+"_MISSING_CELLS",missing.size()+" "+label+" amount"+(missing.size()>1?"s are":" is")+" missing ("+cells(missing)+"). They are left out of the factors that need them, not treated as zero.");if(!zero.isEmpty())warning(out,cl.basis()+"_ZERO_BASE","Some "+label+" amounts are zero and then grow ("+cells(zero)+"); their individual factors are undefined and excluded from simple averages.");
      var thin=cl.factors().stream().filter(f->f.source().equals("ESTIMATED")&&f.pairs()==1).map(f->f.from()+"–"+f.to()).toList();if(!thin.isEmpty())warning(out,cl.basis()+"_SINGLE_PAIR","The "+label+" factors "+String.join(", ",thin)+" rest on a single accident year; consider selecting them with judgement.");var selected=cl.factors().stream().filter(f->f.source().equals("SELECTED")&&f.estimated()!=null&&Math.abs(f.selected()/f.estimated()-1)>.25).map(f->f.from()+"–"+f.to()).toList();if(!selected.isEmpty())warning(out,cl.basis()+"_SELECTION_FAR","The selected "+label+" factors "+String.join(", ",selected)+" differ from the estimate by more than 25%.");var last=cl.factors().get(n-2);if(cl.tail()==1&&last.selected()>1.005)warning(out,cl.basis()+"_TAIL","The last "+label+" factor ("+fixed(last.selected(),4)+") shows development is still under way, but the tail factor is 1: no development is assumed after development year "+n+".");}
    List<String>decreases=new ArrayList<>(),below=new ArrayList<>();for(int i=0;i<n;i++){var row=d.paid().get(i);for(int j=0;j<row.size();j++){Double v=row.get(j);String cell=(d.firstOrigin()+i)+" year "+(j+1);if(j>0&&v!=null&&row.get(j-1)!=null&&v<row.get(j-1))decreases.add(cell);if(d.incurred()!=null&&v!=null&&d.incurred().get(i).get(j)!=null&&d.incurred().get(i).get(j)<v)below.add(cell);}}
    if(!decreases.isEmpty())warning(out,"PAID_DECREASES","Cumulative paid amounts fall in "+cells(decreases)+". This happens with recoveries (salvage, subrogation); check that it is not a data error.");if(!below.isEmpty())warning(out,"NEGATIVE_CASE_RESERVE","Incurred is below paid in "+cells(below)+": the case reserve would be negative. Check the data.");for(int i=0;i<c.methods().size();i++){var e=c.methods().get(i);if(!e.available())continue;var negative=e.origins().stream().filter(o->o.unpaid()<-1e-9).map(o->String.valueOf(o.origin())).toList();if(!negative.isEmpty())warning(out,e.method()+"_NEGATIVE_UNPAID",LABELS.get(i)+" gives an ultimate below the amount already paid for "+String.join(", ",negative)+".");}if(c.incurred()!=null){double gap=c.paid().totals().ultimate()/c.incurred().totals().ultimate()-1;if(Math.abs(gap)>.05)warning(out,"PAID_INCURRED_GAP","Paid and incurred chain ladder ultimates differ by "+fixed(gap*100,1)+"%. Look for changes in payment speed or in case reserve strength before choosing a method.");}if(a.lossRatio()!=null&&d.premiums()==null)warning(out,"LOSS_RATIO_UNUSED","An expected loss ratio was given without earned premiums, so it is not used.");return out;
  }
  static Map<String,Object> comparison(double paid,double incurred){return obj("paidUltimate",paid,"incurredUltimate",incurred,"difference",paid-incurred,"relativeDifference",incurred!=0?paid/incurred-1:null);}
  static double relative(double a,double b){return Math.abs(a-b)/Math.max(1,Math.max(Math.abs(a),Math.abs(b)));}
  static Map<String,Object> analyze(Data d,Assumptions a){validate(d,a);var c=core(d,a);var p=c.paid();var inc=c.incurred();int n=d.paid().size(),year=d.firstOrigin()+n-1;List<Object>reserves=new ArrayList<>(),comp=new ArrayList<>();double paid=0,incurred=0,cases=0;for(int i=0;i<n;i++){var o=p.origins().get(i);Double latest=inc==null?null:inc.origins().get(i).latest(),reserve=latest==null?null:latest-o.latest();paid+=o.latest();if(latest!=null){incurred+=latest;cases+=reserve;}reserves.add(obj("origin",o.origin(),"premium",d.premiums()==null?null:d.premiums().get(i),"paid",o.latest(),"incurred",latest,"caseReserve",reserve));if(inc!=null){var row=obj("origin",o.origin());row.putAll(comparison(o.ultimate(),inc.origins().get(i).ultimate()));comp.add(row);}}
    double maxDifference=0;for(var e:c.methods()){if(!e.available())continue;for(int i=0;i<n;i++){var o=e.origins().get(i);double pa=p.origins().get(i).latest();maxDifference=Math.max(maxDifference,relative(o.unpaid(),o.ultimate()-pa));if(inc!=null)maxDifference=Math.max(maxDifference,relative(o.unpaid(),inc.origins().get(i).latest()-pa+o.ibnr()));}}
    double[]payments=new double[n-1];double tail=0,total=0;for(int i=0;i<n;i++){var row=p.projected().get(i);for(int j=n-i;j<n;j++)payments[i+j-n]+=row.get(j)-row.get(j-1);tail+=row.get(n-1)*(p.tail()-1);}List<Object>periods=new ArrayList<>();for(int t=0;t<payments.length;t++){periods.add(obj("calendarYear",year+t+1,"expectedPayment",payments[t]));total+=payments[t];}total+=tail;
    return obj("modelVersion",VERSION,"firstOrigin",d.firstOrigin(),"origins",IntStream.range(0,n).map(i->d.firstOrigin()+i).boxed().toList(),"valuationYear",year,"averaging",obj("method",a.average(),"latestDiagonals",a.average().equals("LATEST_DIAGONALS")?a.latestDiagonals():null),"chainLadder",obj("paid",p,"incurred",inc),"paidVsIncurred",inc==null?null:obj("origins",comp,"totals",comparison(p.totals().ultimate(),inc.totals().ultimate())),"reserves",obj("origins",reserves,"totals",obj("premium",d.premiums()==null?null:sum(d.premiums()),"paid",paid,"incurred",inc==null?null:incurred,"caseReserve",inc==null?null:cases)),"methods",c.methods().stream().map(Estimate::json).toList(),"reconciliation",obj("holds",maxDifference<1e-9,"maxDifference",maxDifference),"sensitivity",sensitivity(d,a,c),"cashFlows",obj("basis","CHAIN_LADDER_PAID","currency","TND","valuationYear",year,"discounting","NONE","periods",periods,"afterLastDevelopmentYear",tail,"total",total),"warnings",warnings(d,a,c));
  }
}
